CREATE TABLE provisioned_enrollments(organization_id uuid NOT NULL REFERENCES organizations(id),id uuid NOT NULL,connection_id uuid NOT NULL,external_id text NOT NULL,user_name text NOT NULL,email text NOT NULL,display_name text NOT NULL,issuer text NOT NULL,claim_name text NOT NULL,claim_value text NOT NULL,mapping_revision integer NOT NULL,active boolean NOT NULL,state text NOT NULL CHECK(state IN ('PENDING_ENROLLMENT','ACTIVE','SUSPENDED','CANCELLED')),account_id uuid REFERENCES accounts(id),member_id uuid,version integer NOT NULL DEFAULT 1,mailbox_token_hash text UNIQUE,mailbox_expires_at timestamptz,mailbox_verified_at timestamptz,activated_at timestamptz,bound_subject text,created_by uuid NOT NULL REFERENCES accounts(id),updated_at timestamptz NOT NULL DEFAULT clock_timestamp(),PRIMARY KEY(organization_id,id),UNIQUE(organization_id,connection_id,external_id),UNIQUE(organization_id,connection_id,issuer,claim_name,claim_value),FOREIGN KEY(organization_id,member_id) REFERENCES members(organization_id,id));
CREATE TABLE provisioned_enrollment_mail(organization_id uuid NOT NULL,id uuid NOT NULL,enrollment_id uuid NOT NULL,enrollment_version integer NOT NULL,token text,state text NOT NULL DEFAULT 'PENDING' CHECK(state IN ('PENDING','PROCESSING','DELIVERED','FAILED','CANCELLED')),lease_until timestamptz,attempts integer NOT NULL DEFAULT 0,PRIMARY KEY(organization_id,id),FOREIGN KEY(organization_id,enrollment_id) REFERENCES provisioned_enrollments(organization_id,id));
CREATE TABLE provisioned_enrollment_reauth(organization_id uuid NOT NULL,id uuid NOT NULL,enrollment_id uuid NOT NULL,enrollment_version integer NOT NULL,account_id uuid NOT NULL REFERENCES accounts(id),session_id uuid NOT NULL REFERENCES sessions(id) ON DELETE CASCADE,token_hash text NOT NULL UNIQUE,expires_at timestamptz NOT NULL,used_at timestamptz,confirmed boolean NOT NULL CHECK(confirmed),PRIMARY KEY(organization_id,id),FOREIGN KEY(organization_id,enrollment_id) REFERENCES provisioned_enrollments(organization_id,id));
CREATE TABLE provisioned_enrollment_flows(organization_id uuid NOT NULL,id uuid NOT NULL,enrollment_id uuid NOT NULL,enrollment_version integer NOT NULL,cookie_hash text NOT NULL UNIQUE,mailbox_token_hash text NOT NULL,reauth_token_hash text,expires_at timestamptz NOT NULL,consumed_at timestamptz,PRIMARY KEY(organization_id,id),FOREIGN KEY(organization_id,enrollment_id) REFERENCES provisioned_enrollments(organization_id,id));
ALTER TABLE provisioned_enrollments ENABLE ROW LEVEL SECURITY;
ALTER TABLE provisioned_enrollment_mail ENABLE ROW LEVEL SECURITY;
ALTER TABLE provisioned_enrollment_reauth ENABLE ROW LEVEL SECURITY;
ALTER TABLE provisioned_enrollment_flows ENABLE ROW LEVEL SECURITY;
CREATE POLICY tenant ON provisioned_enrollments USING(organization_id=nullif(current_setting('orgmap.organization_id',true),'')::uuid) WITH CHECK(organization_id=nullif(current_setting('orgmap.organization_id',true),'')::uuid);
CREATE POLICY tenant ON provisioned_enrollment_mail USING(organization_id=nullif(current_setting('orgmap.organization_id',true),'')::uuid) WITH CHECK(organization_id=nullif(current_setting('orgmap.organization_id',true),'')::uuid);
CREATE POLICY tenant ON provisioned_enrollment_reauth USING(organization_id=nullif(current_setting('orgmap.organization_id',true),'')::uuid) WITH CHECK(organization_id=nullif(current_setting('orgmap.organization_id',true),'')::uuid);
CREATE POLICY tenant ON provisioned_enrollment_flows USING(organization_id=nullif(current_setting('orgmap.organization_id',true),'')::uuid) WITH CHECK(organization_id=nullif(current_setting('orgmap.organization_id',true),'')::uuid);
GRANT SELECT,INSERT,UPDATE,DELETE ON provisioned_enrollments,provisioned_enrollment_mail,provisioned_enrollment_reauth,provisioned_enrollment_flows TO orgmap_app;
CREATE FUNCTION provisioned_enrollment_lookup(p_hash text,p_kind text) RETURNS TABLE(organization_id uuid,enrollment_id uuid,flow_id uuid) LANGUAGE sql SECURITY DEFINER SET search_path=pg_catalog,public AS $$ SELECT e.organization_id,e.id,NULL::uuid FROM public.provisioned_enrollments e WHERE p_kind='MAILBOX' AND e.mailbox_token_hash=p_hash UNION ALL SELECT f.organization_id,f.enrollment_id,f.id FROM public.provisioned_enrollment_flows f WHERE p_kind='FLOW' AND f.cookie_hash=p_hash $$;
REVOKE ALL ON FUNCTION provisioned_enrollment_lookup(text,text) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION provisioned_enrollment_lookup(text,text) TO orgmap_app;
